draw((0,0)--(4,0)--(3,5)--cycle);
draw(incircle((0,0),(4,0),(3,5)));
real x = 1.15;
pair A = (0,0) + x*(-3,-5);
pair B = (4,0) + x*(1,-5);
draw(A--(3,5)--B--cycle);
draw(incircle(A,(3,5),B));
label("$A$",(3,5),N);
label("$B$",(4,0),E);
label("$C$",(0,0),W);
pair I = incenter((0,0),(3,5),(4,0));
pair iFoot = foot(I,(0,0),(3,5));
label("$S$",iFoot,W);
label("$I$",I,E);
draw(iFoot--I);
pair I2 = incenter(A,(3,5),B);
pair iFoot2 = foot(I2,(0,0),(3,5));
label("$T$",iFoot2,W);
label("$E$",I2,S);
draw(iFoot2--I2);
draw((3,5)--(I2));
[/asy]

